def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    marker = next(v for row in grid for v in row if v not in (0, 9))
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    min_r = min(r for r, c in points)
    min_c = min(c for r, c in points)
    shape = [(r - min_r, c - min_c) for r, c in points]

    for dr in range(h - max(r for r, c in shape)):
        for dc in range(w - max(c for r, c in shape)):
            if all(grid[dr + r][dc + c] == 0 for r, c in shape):
                for r, c in shape:
                    out[dr + r][dc + c] = marker
    return out
